<?php require_once __DIR__.'/../../app/layout.php'; $a=require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $id=(int)($_POST['id']??0); $action=$_POST['action']??'save'; if($action==='delete'&&$id){$pdo->prepare('DELETE FROM notices WHERE id=?')->execute([$id]); audit($pdo,$a['id'],'notice_deleted','notice',$id); flash('Notice deleted.');} else {$title=trim($_POST['title']??'');$description=trim($_POST['description']??''); if($title===''||$description===''){flash('Title and description are required.','error');} elseif($id){$pdo->prepare('UPDATE notices SET title=?,description=?,audience=?,publish_date=?,expiry_date=?,status=? WHERE id=?')->execute([$title,$description,$_POST['audience']??'both',$_POST['publish_date']??date('Y-m-d'),($_POST['expiry_date']??'')?:null,$_POST['status']??'active',$id]);audit($pdo,$a['id'],'notice_updated','notice',$id);flash('Notice updated.');} else {$pdo->prepare('INSERT INTO notices (title,description,audience,publish_date,expiry_date,status) VALUES (?,?,?,?,?,?)')->execute([$title,$description,$_POST['audience']??'both',$_POST['publish_date']??date('Y-m-d'),($_POST['expiry_date']??'')?:null,$_POST['status']??'active']);$id=(int)$pdo->lastInsertId();audit($pdo,$a['id'],'notice_created','notice',$id);flash('Notice published.');} redirect('/admin/notices.php');}}
$edit=['id'=>'','title'=>'','description'=>'','audience'=>'both','publish_date'=>date('Y-m-d'),'expiry_date'=>'','status'=>'active']; if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM notices WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:$edit;} $rows=$pdo->query('SELECT * FROM notices ORDER BY publish_date DESC')->fetchAll(); header_html('Manage notices'); ?>
<h1>Manage notices</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=e((string)$edit['id'])?>"><label>Title<input name="title" value="<?=e($edit['title'])?>" required></label><label>Description<textarea name="description" required><?=e($edit['description'])?></textarea></label><label>Audience<select name="audience"><?php foreach(['public','members','both'] as $v): ?><option value="<?=$v?>" <?=$edit['audience']===$v?'selected':''?>><?=ucfirst($v)?></option><?php endforeach;?></select></label><label>Publish date<input type="date" name="publish_date" value="<?=e($edit['publish_date'])?>" required></label><label>Expiry date (optional)<input type="date" name="expiry_date" value="<?=e((string)$edit['expiry_date'])?>"></label><label>Status<select name="status"><option value="active" <?=$edit['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$edit['status']==='inactive'?'selected':''?>>Inactive</option></select></label><button><?= $edit['id']?'Update':'Publish' ?> notice</button></form><h2>All notices</h2><table><tr><th>Title</th><th>Audience</th><th>Published</th><th>Status</th><th></th></tr><?php foreach($rows as $r): ?><tr><td><?=e($r['title'])?></td><td><?=e($r['audience'])?></td><td><?=e($r['publish_date'])?></td><td><?=e($r['status'])?></td><td><a href="?edit=<?=$r['id']?>">Edit</a><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="delete">Delete</button></form></td></tr><?php endforeach;?></table><?php footer_html();
